select public.prepify_load_bank('Physics', 7, $j$[["Density is defined as:",["mass per unit volume","volume per unit mass","weight per unit area","force per unit volume"],"A",1,0,"6adfc917c329"],["The SI unit of density is:",["kg m⁻³","kg m⁻²","g m","N m⁻³"],"A",1,0,"74e54bf1f2b7"],["A block has a mass of 200 g and a volume of 50 cm³. Its density is:",["0.25 g cm⁻³","4 g cm⁻³","250 g cm⁻³","10 000 g cm⁻³"],"B",3,1,"ec83732ce0e6"],["The density of pure water is about:",["100 kg m⁻³","1000 kg m⁻³","10 000 kg m⁻³","1 kg m⁻³"],"B",1,0,"ed6c7a9a1694"],["What is the mass of 2 m³ of water (density 1000 kg m⁻³)?",["500 kg","1002 kg","2000 kg","0.002 kg"],"C",3,1,"45135ec7557a"],["A substance has a density of 2.5 g cm⁻³. What volume does 500 g of it occupy?",["200 cm³","1250 cm³","502.5 cm³","20 cm³"],"A",5,1,"d600e293793e"],["A wooden block floats on water while an iron nail of the same size sinks. This is because:",["wood is less dense than water and iron is denser","wood is heavier than iron","iron has a smaller volume","water pulls wood upward only"],"A",3,1,"75b016b64316"],["Temperature is a measure of the:",["total heat in a body","average kinetic energy of its particles","mass of the particles","volume of the body"],"B",3,0,"4df3225c381d"],["27 °C on the Kelvin scale is:",["246 K","273 K","300 K","327 K"],"C",1,0,"4028fea8da16"],["0 K is called absolute zero. On the Celsius scale it is about:",["0 °C","−100 °C","−273 °C","273 °C"],"C",1,0,"97a9c1bff371"],["100 °C on the Fahrenheit scale is:",["180 °F","212 °F","100 °F","132 °F"],"B",3,0,"4c40abc4ecec"],["A weather report gives the temperature as 77 °F. In Celsius this is:",["25 °C","45 °C","32 °C","20 °C"],"A",5,1,"748a91863507"],["At which temperature do the Celsius and Fahrenheit scales show the same reading?",["0","−40","32","100"],"B",5,0,"dbca2eca05e5"],["The lower fixed point (ice point) of the Celsius scale is:",["0 °C","4 °C","32 °C","100 °C"],"A",1,0,"2efcfd23ffda"],["A clinical thermometer usually measures temperatures in the range:",["0 °C to 100 °C","35 °C to 42 °C","−10 °C to 110 °C","50 °C to 150 °C"],"B",3,0,"0161164abb6f"],["Alcohol rather than mercury is used in thermometers for very cold places because alcohol:",["has a very low freezing point","is heavier","conducts heat better","is a metal"],"A",3,1,"49494d6e0e13"],["Mercury is useful in thermometers because it:",["expands uniformly and does not wet the glass","is colourless","freezes at room temperature","evaporates quickly"],"A",3,0,"54f888221381"],["Gaps are left between railway track sections because the rails:",["contract in summer","expand when heated in summer","become lighter in winter","need drainage"],"B",3,1,"ae220ecc095e"],["A bimetallic strip bends when heated because the two metals:",["expand by different amounts","have the same expansion","melt at once","lose mass"],"A",3,0,"2e91f5b9b228"],["Water has its maximum density at:",["0 °C","4 °C","37 °C","100 °C"],"B",3,0,"2343dd6ee4d9"],["In winter a lake freezes from the top downward, so fish survive in the water below. This happens mainly because:",["ice is denser than water","water is densest at 4 °C and ice floats","fish produce heat","the bottom of the lake is warmer due to sunlight"],"B",5,1,"856cfe368072"],["A metal lid on a glass jar is stuck. Pouring hot water over the lid helps because:",["the metal expands more than the glass","the glass expands more than the metal","hot water is a lubricant","heat reduces friction to zero"],"A",3,1,"6876cc143fea"],["Heat and temperature differ because heat is:",["the energy transferred due to a temperature difference","always measured in kelvin","the same as temperature","a property of particles at rest"],"A",3,0,"8a6c2b1bfc75"],["When a gas is heated in a sealed container, its particles:",["slow down","move faster","stop moving","shrink"],"B",3,0,"724b3dd5ed8f"],["A student measures the mass of a stone as 60 g and finds it raises the water in a measuring cylinder from 40 cm³ to 60 cm³. The stone's density is:",["1.5 g cm⁻³","3 g cm⁻³","1 g cm⁻³","20 g cm⁻³"],"B",5,1,"f0ff009bb247"],["Which of these has the lowest density?",["Iron","Water","Air","Glass"],"C",1,0,"6cd02de19c26"],["The temperature of a body rises from 20 °C to 50 °C. The rise in temperature on the Kelvin scale is:",["30 K","303 K","323 K","273 K"],"A",5,0,"b601472c3a70"],["Overhead electric wires are left slightly slack in summer so that in winter they:",["do not snap when they contract","can expand more","carry more current","look straight"],"A",3,1,"b1a8bd521ccc"],["The instrument used to measure temperature is the:",["barometer","thermometer","hygrometer","manometer"],"B",1,0,"2e5a4ffdee9a"],["If equal masses of two liquids have volumes of 100 cm³ and 50 cm³, the liquid with volume 50 cm³ has:",["half the density","the same density","twice the density","four times the density"],"C",5,0,"6467ed799333"],["The instrument used to measure atmospheric pressure is the:",["thermometer","barometer","hygrometer","ammeter"],"B",1,0,"2e5a4ffdee9a"],["Absolute zero (0 K) is the temperature at which:",["water freezes","the particles of a substance have the least possible energy","water boils","mercury melts"],"B",3,0,"97a9c1bff371"],["An ice cube floats on water because ice is:",["denser than water","less dense than water","heavier than water","hotter than water"],"B",1,1,"75b016b64316"],["The upper fixed point (steam point) of the Celsius scale is:",["0 °C","37 °C","100 °C","212 °C"],"C",1,0,"2efcfd23ffda"],["The density of a substance is its:",["mass per unit volume","volume per unit mass","weight per unit area","mass times volume"],"A",1,0,"74e54bf1f2b7"],["A block has a mass of 100 g and a volume of 25 cm³. Its density is:",["2500 g cm⁻³","4 g cm⁻³","40 g cm⁻³","0.25 g cm⁻³"],"B",3,0,"ec83732ce0e6"],["A block has a mass of 300 g and a volume of 100 cm³. Its density is:",["30,000 g cm⁻³","3 g cm⁻³","0.333 g cm⁻³","30 g cm⁻³"],"B",3,0,"ec83732ce0e6"],["A block has a mass of 32 g and a volume of 40 cm³. Its density is:",["1.25 g cm⁻³","0.8 g cm⁻³","8 g cm⁻³","1280 g cm⁻³"],"B",3,0,"ec83732ce0e6"],["A block has a mass of 25 g and a volume of 10 cm³. Its density is:",["2.5 g cm⁻³","250 g cm⁻³","0.4 g cm⁻³","25 g cm⁻³"],"A",3,0,"ec83732ce0e6"],["A block has a mass of 60 g and a volume of 20 cm³. Its density is:",["0.333 g cm⁻³","3 g cm⁻³","1200 g cm⁻³","30 g cm⁻³"],"B",3,0,"ec83732ce0e6"],["A block has a mass of 320 g and a volume of 40 cm³. Its density is:",["12,800 g cm⁻³","0.125 g cm⁻³","8 g cm⁻³","80 g cm⁻³"],"C",3,0,"ec83732ce0e6"],["What is the mass of 4 m³ of kerosene (density 800 kg m⁻³)?",["200 kg","0.005 kg","804 kg","3200 kg"],"D",3,0,"45135ec7557a"],["What is the mass of 5 m³ of water (density 1000 kg m⁻³)?",["200 kg","5000 kg","1005 kg","0.005 kg"],"B",3,0,"45135ec7557a"],["What is the mass of 2 m³ of cooking oil (density 900 kg m⁻³)?",["450 kg","1800 kg","902 kg","0.0022 kg"],"B",3,0,"45135ec7557a"],["What is the mass of 5 m³ of kerosene (density 800 kg m⁻³)?",["0.0063 kg","160 kg","4000 kg","805 kg"],"C",3,0,"45135ec7557a"],["What is the mass of 4 m³ of cooking oil (density 900 kg m⁻³)?",["0.0044 kg","904 kg","3600 kg","225 kg"],"C",3,0,"45135ec7557a"],["What is the mass of 0.5 m³ of cooking oil (density 900 kg m⁻³)?",["900.5 kg","0.0006 kg","1800 kg","450 kg"],"D",3,0,"45135ec7557a"],["A substance has a density of 10 g cm⁻³. What volume does 1000 g of it occupy?",["10,000 cm³","1010 cm³","0.01 cm³","100 cm³"],"D",3,0,"d600e293793e"],["A substance has a density of 8 g cm⁻³. What volume does 400 g of it occupy?",["0.02 cm³","408 cm³","3200 cm³","50 cm³"],"D",3,0,"d600e293793e"],["A substance has a density of 10 g cm⁻³. What volume does 400 g of it occupy?",["410 cm³","0.025 cm³","4000 cm³","40 cm³"],"D",3,0,"d600e293793e"],["A substance has a density of 8 g cm⁻³. What volume does 800 g of it occupy?",["808 cm³","6400 cm³","100 cm³","0.01 cm³"],"C",3,0,"d600e293793e"],["A substance has a density of 2.5 g cm⁻³. What volume does 100 g of it occupy?",["250 cm³","102.5 cm³","0.025 cm³","40 cm³"],"D",3,0,"d600e293793e"],["A substance has a density of 4 g cm⁻³. What volume does 400 g of it occupy?",["404 cm³","100 cm³","0.01 cm³","1600 cm³"],"B",3,0,"d600e293793e"],["A temperature of 323 K on the Celsius scale is:",["50 °C","596 °C","323 °C","−50 °C"],"A",1,0,"4028fea8da16"],["A temperature of 373 K on the Celsius scale is:",["646 °C","373 °C","−100 °C","100 °C"],"D",1,0,"4028fea8da16"],["A temperature of 290 K on the Celsius scale is:",["17 °C","290 °C","−17 °C","563 °C"],"A",1,0,"4028fea8da16"],["A temperature of 400 K on the Celsius scale is:",["127 °C","−127 °C","400 °C","673 °C"],"A",1,0,"4028fea8da16"],["227 °C on the Kelvin scale is:",["600 K","500 K","46 K","−46 K"],"B",1,0,"4028fea8da16"],["37 °C on the Kelvin scale is:",["−236 K","236 K","410 K","310 K"],"D",1,0,"4028fea8da16"],["10 °C on the Fahrenheit scale is:",["50 °F","18 °F","37.6 °F","42 °F"],"A",3,0,"4c40abc4ecec"],["60 °C on the Fahrenheit scale is:",["140 °F","92 °F","108 °F","65.3 °F"],"A",3,0,"4c40abc4ecec"],["40 °C on the Fahrenheit scale is:",["40 °F","72 °F","54.2 °F","104 °F"],"D",3,0,"4c40abc4ecec"],["50 °C on the Fahrenheit scale is:",["90 °F","59.8 °F","122 °F","82 °F"],"C",3,0,"4c40abc4ecec"],["25 °C on the Fahrenheit scale is:",["45.9 °F","45 °F","57 °F","77 °F"],"D",3,0,"4c40abc4ecec"],["30 °C on the Fahrenheit scale is:",["48.7 °F","62 °F","54 °F","86 °F"],"D",3,0,"4c40abc4ecec"],["A weather report gives the temperature as 86 °F. In Celsius this is:",["186.8 °C","40 °C","54 °C","30 °C"],"D",3,1,"748a91863507"],["A weather report gives the temperature as 59 °F. In Celsius this is:",["25 °C","27 °C","138.2 °C","15 °C"],"D",3,1,"748a91863507"],["A weather report gives the temperature as 95 °F. In Celsius this is:",["63 °C","203 °C","35 °C","45 °C"],"C",3,1,"748a91863507"],["A weather report gives the temperature as 50 °F. In Celsius this is:",["18 °C","10 °C","122 °C","20 °C"],"B",3,1,"748a91863507"],["A weather report gives the temperature as 104 °F. In Celsius this is:",["40 °C","50 °C","219.2 °C","72 °C"],"A",3,1,"748a91863507"],["A weather report gives the temperature as 68 °F. In Celsius this is:",["36 °C","20 °C","154.4 °C","30 °C"],"B",3,1,"748a91863507"],["How much heat is needed to raise the temperature of 0.5 kg of water by 40 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["84,000 J","8400 J","2100 J","168,000 J"],"A",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to raise the temperature of 1 kg of water by 50 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["21,000 J","4200 J","2,100,000 J","210,000 J"],"D",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to raise the temperature of 2 kg of water by 25 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["105,000 J","8400 J","210,000 J","21,000 J"],"C",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to raise the temperature of 1 kg of water by 20 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["4200 J","840,000 J","8400 J","84,000 J"],"D",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to raise the temperature of 1 kg of water by 25 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["4200 J","1,050,000 J","10,500 J","105,000 J"],"D",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to raise the temperature of 1 kg of water by 40 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)",["4200 J","1,680,000 J","168,000 J","16,800 J"],"C",5,0,"gen-physics-p7-specific-heat"],["How much heat is needed to melt 0.5 kg of ice already at 0 °C? (specific latent heat of fusion of ice = 336,000 J/kg)",["2100 J","672,000 J","1,680,000 J","168,000 J"],"D",5,1,"gen-physics-p7-latent-heat"],["How much heat is needed to melt 0.25 kg of ice already at 0 °C? (specific latent heat of fusion of ice = 336,000 J/kg)",["84,000 J","1050 J","1,344,000 J","840,000 J"],"A",5,1,"gen-physics-p7-latent-heat"],["How much heat is needed to melt 5 kg of ice already at 0 °C? (specific latent heat of fusion of ice = 336,000 J/kg)",["1,680,000 J","21,000 J","67,200 J","16,800,000 J"],"A",5,1,"gen-physics-p7-latent-heat"],["How much heat is needed to melt 3 kg of ice already at 0 °C? (specific latent heat of fusion of ice = 336,000 J/kg)",["112,000 J","1,008,000 J","10,080,000 J","12,600 J"],"B",5,1,"gen-physics-p7-latent-heat"],["How much heat is needed to melt 2 kg of ice already at 0 °C? (specific latent heat of fusion of ice = 336,000 J/kg)",["168,000 J","8400 J","6,720,000 J","672,000 J"],"D",5,1,"gen-physics-p7-latent-heat"],["A steel rail 10 m long is heated through 100 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["1200 mm","1.2 mm","120 mm","12 mm"],"D",5,1,"gen-physics-p7-expansion"],["A steel rail 50 m long is heated through 50 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["300 mm","3000 mm","3 mm","30 mm"],"D",5,1,"gen-physics-p7-expansion"],["A steel rail 50 m long is heated through 20 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["120 mm","12 mm","1.2 mm","1200 mm"],"B",5,1,"gen-physics-p7-expansion"],["A steel rail 20 m long is heated through 40 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["960 mm","9.6 mm","0.96 mm","96 mm"],"B",5,1,"gen-physics-p7-expansion"],["A steel rail 10 m long is heated through 20 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["24 mm","240 mm","2.4 mm","0.24 mm"],"C",5,1,"gen-physics-p7-expansion"],["A steel rail 10 m long is heated through 40 °C. If the coefficient of linear expansion of steel is 1.2 × 10⁻⁵ per °C, its increase in length is:",["48 mm","4.8 mm","480 mm","0.48 mm"],"B",5,1,"gen-physics-p7-expansion"],["An object has a mass of 30 g and a volume of 50 cm³. When placed in water (density 1 g cm⁻³), it will:",["sink, because its density is 0.6 g cm⁻³","sink, because its mass is 30 g","float, because its volume is 50 cm³","float, because its density is 0.6 g cm⁻³"],"D",3,1,"gen-physics-p7-float-or-sink"],["An object has a mass of 150 g and a volume of 50 cm³. When placed in water (density 1 g cm⁻³), it will:",["float, because its density is 3 g cm⁻³","sink, because its density is 3 g cm⁻³","float, because its mass is 150 g","sink, because its volume is 50 cm³"],"B",3,1,"gen-physics-p7-float-or-sink"],["An object has a mass of 100 g and a volume of 50 cm³. When placed in water (density 1 g cm⁻³), it will:",["sink, because its volume is 50 cm³","sink, because its density is 2 g cm⁻³","float, because its mass is 100 g","float, because its density is 2 g cm⁻³"],"B",3,1,"gen-physics-p7-float-or-sink"],["An object has a mass of 16 g and a volume of 40 cm³. When placed in water (density 1 g cm⁻³), it will:",["float, because its density is 0.4 g cm⁻³","sink, because its density is 0.4 g cm⁻³","float, because its volume is 40 cm³","sink, because its mass is 16 g"],"A",3,1,"gen-physics-p7-float-or-sink"],["An object has a mass of 30 g and a volume of 20 cm³. When placed in water (density 1 g cm⁻³), it will:",["sink, because its volume is 20 cm³","float, because its mass is 30 g","sink, because its density is 1.5 g cm⁻³","float, because its density is 1.5 g cm⁻³"],"C",3,1,"gen-physics-p7-float-or-sink"],["An object has a mass of 12 g and a volume of 20 cm³. When placed in water (density 1 g cm⁻³), it will:",["float, because its density is 0.6 g cm⁻³","float, because its volume is 20 cm³","sink, because its mass is 12 g","sink, because its density is 0.6 g cm⁻³"],"A",3,1,"gen-physics-p7-float-or-sink"]]$j$::jsonb, true);
select public.prepify_load_bank('Physics', 8, $j$[["Like magnetic poles:",["attract each other","repel each other","have no effect on each other","cancel each other's magnetism"],"B",1,0,"a770c340d6d5"],["Which of these is a magnetic material?",["Copper","Aluminium","Iron","Wood"],"C",1,0,"07536ad27846"],["Which group contains only magnetic materials?",["Iron, nickel, cobalt","Iron, copper, zinc","Nickel, gold, silver","Cobalt, aluminium, tin"],"A",3,0,"59c6fe0b2e7e"],["Outside a bar magnet, magnetic field lines go from:",["south pole to north pole","north pole to south pole","the middle to both ends","both ends to the middle"],"B",3,0,"c9274736d248"],["A freely suspended bar magnet comes to rest pointing:",["east–west","north–south","up–down","in any direction"],"B",1,0,"066c6988fc71"],["The Earth's geographic North Pole is near a magnetic:",["north pole","south pole","equator","neutral point"],"B",5,0,"96935460aeda"],["Soft iron is used in electromagnets because it:",["is easily magnetized and easily loses its magnetism","keeps its magnetism permanently","is not magnetic","is very heavy"],"A",3,0,"4b0e4a48de61"],["Steel is used for permanent magnets because it:",["keeps its magnetism for a long time","loses its magnetism quickly","is non-magnetic","is a good insulator"],"A",3,0,"cf905c137944"],["A student strokes an iron nail many times in one direction with a magnet. The nail:",["becomes magnetized","becomes electrically charged","melts","loses its mass"],"A",3,1,"943ac07b3d40"],["Which of these will destroy a magnet's magnetism?",["Heating it strongly or hammering it","Keeping it with a keeper","Storing it in pairs","Cooling it slightly"],"A",3,0,"32b269efa87c"],["According to domain theory, an unmagnetized piece of iron has domains that are:",["all aligned in one direction","randomly arranged","absent","all pointing south"],"B",5,0,"525247330e21"],["Field lines close together show that the magnetic field is:",["weak","strong","zero","reversed"],"B",3,0,"87dce209bdcc"],["A crane at a scrapyard lifts iron scrap and drops it when switched off. It uses:",["a permanent magnet","an electromagnet","a bar of copper","a compass"],"B",3,1,"7e19392c6421"],["The strength of an electromagnet can be increased by:",["increasing the current and the number of turns","decreasing the current","removing the iron core","using fewer turns"],"A",3,0,"f3ca79e9d622"],["A magnetic compass needle is:",["a small magnet","a piece of copper","a charged plastic strip","a piece of glass"],"A",1,0,"4f3af355276c"],["A current-carrying straight wire produces a magnetic field that is:",["in straight lines along the wire","in circles around the wire","zero","only at the ends of the wire"],"B",5,0,"9131237ac267"],["The direction of the magnetic field around a current-carrying wire is given by the:",["right-hand grip rule","left-hand rule for motors only","head-to-tail rule","parallelogram law"],"A",5,0,"ea4650f6abc8"],["A student brings a magnet near a paper clip without touching it and the clip is attracted. This shows magnetism can act:",["only by contact","at a distance","only in water","only on plastics"],"B",3,1,"94e6834c33a5"],["Which device uses an electromagnet?",["Electric bell","Torch bulb","Candle","Mirror"],"A",1,0,"5717920dc372"],["A magnet is broken into two pieces. Each piece:",["has only one pole","becomes a complete magnet with a north and a south pole","loses all magnetism","becomes a south pole only"],"B",5,0,"e813ea90a30d"],["Iron filings sprinkled around a bar magnet gather most thickly:",["at the middle","near the poles","nowhere","in a straight line"],"B",3,0,"46b753f6234f"],["Which method can make a temporary magnet from an iron bar?",["Placing it near a strong magnet (induction)","Painting it","Cooling it","Wrapping it in cloth"],"A",3,0,"001b60eb60cc"],["A sensitive watch is kept inside a soft iron box near strong magnets. The box:",["shields the watch from magnetic fields","magnetizes the watch","charges the watch","heats the watch"],"A",5,1,"0c0e48bdc8c4"],["Which is NOT a use of magnets?",["Loudspeakers","MRI machines","Compasses","Measuring temperature"],"D",1,0,"9156a2ed167a"],["A magnet attracts:",["wood","iron","plastic","rubber"],"B",1,0,"abdae0963ba4"],["Two magnets are placed with a north pole facing a south pole. They will:",["repel","attract","rotate away","lose magnetism"],"B",1,0,"834e9ed2bec9"],["The region around a magnet where its magnetic force can be felt is called its:",["magnetic field","electric field","gravitational field","domain"],"A",1,0,"30104bcc0231"],["A hiker's compass points wrongly when held next to a steel knife. This is because:",["the steel's magnetic field disturbs the needle","the knife is charged","steel is non-magnetic","the Earth's field has disappeared"],"A",3,1,"f6e2857922c3"],["Reversing the direction of current in an electromagnet:",["reverses its poles","destroys it","doubles its strength","has no effect"],"A",5,0,"f44cb7d4fc89"],["Magnetic field lines of a magnet:",["never cross each other","always cross at the poles","form straight parallel lines everywhere","start and end at the middle"],"A",5,0,"18a1937d888e"],["Around a long straight wire carrying current, the magnetic field lines form:",["straight lines parallel to the wire","concentric circles around the wire","no pattern","lines only at the ends"],"B",5,0,"9131237ac267"],["A compass needle points wrongly when placed near a steel scissors. This happens because:",["the steel's magnetic field affects the needle","the scissors are charged","steel is non-magnetic","the compass is broken"],"A",3,1,"f6e2857922c3"],["Iron filings sprinkled around a bar magnet are least crowded:",["near the north pole","near the south pole","near the middle of the magnet","at both ends"],"C",5,0,"46b753f6234f"],["Inside a bar magnet, magnetic field lines run from:",["north pole to south pole","south pole to north pole","the middle outwards","nowhere"],"B",5,0,"c9274736d248"],["The core of an electromagnet in a scrapyard crane is made of soft iron because soft iron:",["is easily magnetized and demagnetized","keeps its magnetism forever","is non-magnetic","is very light"],"A",3,1,"4b0e4a48de61"],["A magnet picks up a steel pin through a sheet of paper. This shows that magnetic force:",["acts only by contact","can act at a distance and through paper","needs air","works only in water"],"B",3,1,"94e6834c33a5"],["Where magnetic field lines are far apart, the field is:",["strong","weak","zero","reversed"],"B",3,0,"87dce209bdcc"],["A magnet loses its magnetism if it is:",["stored with keepers","dropped repeatedly or heated strongly","kept in pairs","kept in a dry place"],"B",3,0,"32b269efa87c"],["Which of these uses an electromagnet?",["Candle","Door bell","Mirror","Glass jar"],"B",1,0,"5717920dc372"]]$j$::jsonb, true);
select public.prepify_load_bank('Physics', 9, $j$[["Physics is the branch of science that deals with:",["living things","matter, energy and their interactions","the Earth's rocks","chemical reactions only"],"B",1,0,"9870c0b760e2"],["The study of heat and temperature is a branch of physics called:",["optics","thermodynamics","acoustics","mechanics"],"B",1,0,"004e29d3d8a1"],["The branch of physics that deals with light is:",["optics","mechanics","nuclear physics","electricity"],"A",1,0,"d52860c4b673"],["The study of sound is called:",["acoustics","optics","astronomy","geology"],"A",1,0,"50c76c19abdc"],["The branch of physics that deals with the nucleus of the atom is:",["atomic physics","nuclear physics","plasma physics","mechanics"],"B",3,0,"588295b39572"],["The study of motion and forces is called:",["mechanics","optics","electronics","thermodynamics"],"A",1,0,"633966863980"],["A scientist suggests a possible explanation that can be tested by experiment. This explanation is called a:",["law","hypothesis","theory proven forever","conclusion"],"B",3,0,"64b53074a5f6"],["A hypothesis that has been tested and supported by a lot of evidence may become a:",["guess","theory","myth","question"],"B",3,0,"81deb39805b0"],["The scientific method usually begins with:",["observation","a final conclusion","publishing results","a guess without evidence"],"A",1,0,"6a36cf9bc706"],["A student tests whether plant height depends on the amount of water. The amount of water given is the:",["independent variable","dependent variable","control","constant"],"A",3,1,"62765160fbb5"],["In the same plant experiment, the height of the plant is the:",["independent variable","dependent variable","constant","hypothesis"],"B",3,1,"3dedb68a9231"],["In a fair test, the variables kept the same are called:",["controlled variables","independent variables","dependent variables","results"],"A",3,0,"5dc702f40115"],["Why do scientists repeat an experiment several times?",["To make the results more reliable","To use more equipment","To change the hypothesis each time","To avoid writing a report"],"A",3,0,"a1ed36e670c2"],["Physics contributes to technology because:",["many devices are built on physics principles","technology has nothing to do with science","physics only studies the past","physics is only theoretical"],"A",1,0,"b9b5f5ca69ff"],["The technology behind X-ray and MRI machines in hospitals comes mainly from:",["physics","geography","history","literature"],"A",3,1,"85a8953dde47"],["A mobile phone works using principles of electromagnetic waves. This shows the link between physics and:",["technology","art","music","sports"],"A",3,1,"e0b5ef49c503"],["A scientific theory is different from a guess because it:",["is supported by evidence and can be tested","is just an opinion","can never be changed","has no evidence"],"A",3,0,"0eef43a4473b"],["Scientific knowledge can change over time because:",["new evidence may improve or correct it","scientists are careless","science has no rules","facts never matter"],"A",3,0,"c5df98cdd10d"],["Which field combines physics with the study of living things?",["Biophysics","Astrophysics","Geophysics","Nuclear physics"],"A",3,0,"1b83f56baab7"],["The study of the Earth using physics, such as earthquakes, is called:",["geophysics","biophysics","acoustics","optics"],"A",3,0,"767127b38140"],["The study of stars and planets using physics is:",["astrophysics","biophysics","thermodynamics","electronics"],"A",1,0,"461d765bec71"],["A researcher wants to know whether a new material is a good conductor of heat. The best first step is to:",["design and carry out a fair experiment","announce the result without testing","ask friends to guess","ignore the material"],"A",3,1,"0356f9e4e673"],["Which of these is a quantitative observation?",["The liquid is blue","The rod is 25 cm long","The flower smells sweet","The sound is pleasant"],"B",5,0,"894618e452a4"],["Which of these is a qualitative observation?",["The mass is 5 kg","The temperature is 30 °C","The solution is cloudy","The time is 10 s"],"C",5,0,"d68fcd857444"],["A scientist records data in a table and then draws a graph. The main purpose of the graph is to:",["show the relationship between variables clearly","hide the data","replace the experiment","make the report longer"],"A",3,0,"ad07d9af2b96"],["Solar panels convert light energy into electrical energy. This technology is based on:",["physics","poetry","economics","history"],"A",1,0,"58cf75c87565"],["When results of an experiment do not support the hypothesis, a scientist should:",["reject or modify the hypothesis","change the data","ignore the results","stop doing science"],"A",3,1,"84a58f43a5bb"],["Engineering differs from science because engineering mainly:",["applies scientific knowledge to design solutions","discovers laws of nature only","studies ancient history","avoids using science"],"A",3,0,"b9c67d760af8"],["A physicist studies electrons flowing through circuits. This branch is:",["electricity and electronics","optics","acoustics","thermodynamics"],"A",3,0,"2b536b7871ec"],["Ethics in science means scientists should:",["report results honestly","copy others' work","change results to look better","hide mistakes"],"A",1,0,"aba41fe7aa5f"],["The study of light and how it behaves is called:",["acoustics","optics","geology","astronomy"],"B",1,0,"50c76c19abdc"],["Using physics to study the Earth's interior and earthquakes is called:",["geophysics","biophysics","astrophysics","acoustics"],"A",3,0,"1b83f56baab7"],["A tested explanation that has been supported by many experiments over time becomes a:",["guess","theory","hypothesis only","opinion"],"B",3,0,"64b53074a5f6"],["Which of these is a quantitative observation?",["The liquid is blue","The metal is shiny","The rod is 25 cm long","The smell is strong"],"C",5,0,"d68fcd857444"],["A student tests how the height of a ramp affects a ball's speed. The speed measured is the:",["independent variable","dependent variable","controlled variable","constant"],"B",3,1,"62765160fbb5"],["Solar panels that turn sunlight into electricity show the link between physics and:",["technology","poetry","history","sport"],"A",1,1,"e0b5ef49c503"],["Earlier ideas in science are sometimes changed because:",["new evidence can improve or correct them","scientists enjoy changing them","science has no rules","old books are lost"],"A",3,0,"c5df98cdd10d"],["The study of heat and its conversion into other forms of energy is:",["thermodynamics","optics","acoustics","electronics"],"A",3,0,"2b536b7871ec"]]$j$::jsonb, true);
